}

export function getChronicleGear(raw, actorId, slot) {
  const session = normalizeChronicle(raw);
  if (!session || !session.party.includes(actorId)
    || slot !== undefined && !['weapon', 'armor', 'weaponMod', 'weaponMod2'].includes(slot)) return [];
