        || !Number.isFinite(contact.x) || !Number.isFinite(contact.z)
        || contact.x < bounds.minX + .4 || contact.x > bounds.maxX - .4 || contact.z < bounds.minZ + .4 || contact.z > bounds.maxZ - .4) continue;
